128	 * an adapter knows the intents and nothing else about remote_ctrl -- and
129	 * remote_ctrl never learns what hardware the product has.  A product with a
130	 * touch screen registers a different adapter and leaves the channel
131	 * untouched.
132	 */
133	typedef void (*remote_decide_fn)(enum remote_decision_e decision, void *ctx);
134	typedef int  (*remote_pending_fn)(void *ctx);      /* 1 when an approval is up */
135	typedef void (*remote_scroll_fn)(int dir, void *ctx); /* 0=older, 1=newer */
136	typedef void (*remote_action_fn)(void *ctx);          /* model-next / new-session */
137	typedef int  (*remote_wake_fn)(void *ctx);            /* 1 when it ate the press as a wake */
138	typedef int  (*remote_dismiss_fn)(void *ctx);         /* 1 when it ate the press as a page dismiss */
139	
140	struct remote_input_ops_s
141	{
142	  const char *name;                       /* "keymap" / "touch" / "voice" */
143	
144	  /* The adapter receives the *application* surface, not raw button indices:
145	   * it maps its gesture vocabulary onto decide / scroll / model / session and
146	   * the channel owns the semantics.  Every callback except `decide` is
147	   * optional -- a product with no transcript leaves `scroll` NULL and the
148	   * channel simply never offers it.  `pending` lets the adapter pick a key
149	   * context (idle keys scroll, approval keys decide) without reading session
150	   * state itself.  `dismiss` and `wake` are "consume or pass" gates the
151	   * adapter must try BEFORE the keymap: a notice page (5 s) or the standby
152	   * clock owns the press and swallows it. */
153	  int (*attach)(remote_decide_fn decide,
154	                remote_pending_fn pending,
155	                remote_scroll_fn scroll,
156	                remote_action_fn model_next,
157	                remote_action_fn session_new,
158	                remote_dismiss_fn dismiss,
159	                remote_wake_fn wake,
160	                void *ctx);
161	  void (*detach)(void);
162	};
