64	#define PET_TYPE_CONFIG_KEY "pet_type"
65	
66	/* Pick the species for this boot.
67	 *
68	 * The pet must NOT change as the user moves between pages, so the species is
69	 * a boot-time constant rather than a UI toggle: read it back from the config
70	 * store (survives reboots, wiped by a full flash), or pick one at random the
71	 * first time and persist it.  The pick is logged so a test run can tell which
72	 * sprite should be on screen.
73	 */
74	static int pet_type_fixed(void)
75	{
76	  char buf[8];
77	  unsigned char rnd = 0;
78	  int type;
79	
80	  if (claw_config_get(PET_TYPE_CONFIG_KEY, buf, sizeof(buf)) == OK &&
81	      buf[0] != '\0')
82	    {
83	      type = atoi(buf);
84	      if (type >= 0 && type < PET_TYPE_COUNT)
85	        {
86	          syslog(LOG_INFO, "[%s] fixed type %d (from config)\n", TAG, type);
87	          return type;
88	        }
89	    }
90	
91	  if (agent_secure_random(&rnd, sizeof(rnd)) != 0)
92	    {
93	      /* No /dev/urandom: boot time + stack address is still different enough
94	       * between two flashes that the choice does not look constant. */
95	      rnd = (unsigned char)((uint32_t)clock() ^ (uint32_t)time(NULL) ^
96	                            (uint32_t)(uintptr_t)&type);
97	    }
98	  type = (int)(rnd % PET_TYPE_COUNT);
99	
100	  snprintf(buf, sizeof(buf), "%d", type);
101	  if (claw_config_set(PET_TYPE_CONFIG_KEY, buf) != OK)
102	    {
103	      syslog(LOG_WARNING, "[%s] type %d not persisted (no config store)\n",
104	             TAG, type);
105	    }
106	  syslog(LOG_INFO, "[%s] fixed type %d (new random pick)\n", TAG, type);
107	  return type;
108	}
